import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../services/api.service';

interface Drive {
  id: number;
  companyName: string;
  role: string;
  packageAmount: number;
  location: string;
  eligibility: string;
  description: string;
  applyLink: string;
  deadline: string;
  isActive: boolean;
  planId?: number;
  driveType?: 'INTERNAL' | 'EXTERNAL';
}

interface InterviewSlot {
  id: number;
  driveId: number;
  slotTime: string;
  location?: string;
  notes?: string;
  bookedByUserId?: number;
  status: 'AVAILABLE' | 'BOOKED' | 'COMPLETED' | 'CANCELLED';
}

interface StudentApplication {
  id: number;
  user: { id: number; name?: string; fullName?: string; email?: string };
  companyName: string;
  role: string;
  driveId?: number;
  status: 'OPEN' | 'APPLIED' | 'SELECTED' | 'REJECTED';
  placedDate?: string;
}

interface SubscriptionPlan {
  id: number;
  name: string;
  price: number;
  period: string;
}

@Component({
  selector: 'app-placements',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
      <h1 style="font-size:24px;font-weight:700;">Placement Drives</h1>
      <button class="btn btn-primary" (click)="openAddModal()">+ Add Drive</button>
    </div>

    <div class="card">
      <table>
        <thead>
          <tr><th>Company</th><th>Role</th><th>Type</th><th>Package</th><th>Location</th><th>Plan</th><th>Deadline</th><th>Status</th><th>Actions</th></tr>
        </thead>
        <tbody>
          <tr *ngFor="let d of drives">
            <td>{{d.companyName}}</td>
            <td>{{d.role}}</td>
            <td>
              <span class="badge" [class.badge-success]="d.driveType === 'INTERNAL'" [class.badge-info]="d.driveType !== 'INTERNAL'">
                {{ d.driveType === 'INTERNAL' ? '🏢 Internal' : '🌐 External' }}
              </span>
            </td>
            <td>{{d.packageAmount ? '₹' + d.packageAmount + ' LPA' : '-'}}</td>
            <td>{{d.location || '-'}}</td>
            <td>
              <span *ngIf="getPlanName(d.planId)" class="badge badge-warning">⭐ {{getPlanName(d.planId)}}</span>
              <span *ngIf="!getPlanName(d.planId)" style="color:#64748B;font-size:13px;">No plan</span>
            </td>
            <td>{{d.deadline ? (d.deadline | slice:0:10) : '-'}}</td>
            <td><span class="badge" [class.badge-success]="d.isActive" [class.badge-danger]="!d.isActive">{{d.isActive ? 'Active' : 'Inactive'}}</span></td>
            <td>
              <button *ngIf="d.driveType === 'INTERNAL'" class="btn btn-secondary" style="padding:4px 12px;font-size:12px;margin-right:8px;" (click)="openSlotsModal(d)">Slots</button>
              <button class="btn btn-secondary" style="padding:4px 12px;font-size:12px;margin-right:8px;" (click)="openEditModal(d)">Edit</button>
              <button class="btn btn-danger" style="padding:4px 12px;font-size:12px;" (click)="deleteDrive(d)">Delete</button>
            </td>
          </tr>
          <tr *ngIf="drives.length === 0">
            <td colspan="9" style="text-align:center;color:#64748B;padding:32px;">No placement drives found. Click "+ Add Drive" to create one.</td>
          </tr>
        </tbody>
      </table>
    </div>

    <h2 style="font-size:18px;font-weight:700;margin:32px 0 16px;">Student Applications</h2>
    <div class="card">
      <table>
        <thead>
          <tr><th>Student</th><th>Company</th><th>Role</th><th>Status</th><th>Actions</th></tr>
        </thead>
        <tbody>
          <tr *ngFor="let a of applications">
            <td>{{ a.user?.fullName || a.user?.name || a.user?.email || 'Unknown' }}</td>
            <td>{{ a.companyName }}</td>
            <td>{{ a.role }}</td>
            <td>
              <span class="badge"
                    [class.badge-success]="a.status === 'SELECTED'"
                    [class.badge-warning]="a.status === 'APPLIED'"
                    [class.badge-danger]="a.status === 'REJECTED'">
                {{ a.status }}
              </span>
            </td>
            <td>
              <select [ngModel]="a.status" (ngModelChange)="updateApplicationStatus(a, $event)"
                      style="padding:6px;border:1px solid #E2E8F0;border-radius:6px;font-size:12px;">
                <option value="OPEN">Open</option>
                <option value="APPLIED">Applied</option>
                <option value="SELECTED">Selected</option>
                <option value="REJECTED">Rejected</option>
              </select>
            </td>
          </tr>
          <tr *ngIf="applications.length === 0">
            <td colspan="5" style="text-align:center;color:#64748B;padding:32px;">No student applications yet.</td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- Drive Modal -->
    <div class="modal-overlay" *ngIf="showModal" (click)="closeModal($event)">
      <div class="modal-content" style="width:90%;max-width:520px;" (click)="$event.stopPropagation()">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
          <h2 style="font-size:20px;font-weight:700;">{{editingDrive ? 'Edit Drive' : 'Add New Drive'}}</h2>
          <button class="btn btn-secondary" (click)="closeModal()">✕</button>
        </div>

        <form (ngSubmit)="saveDrive()">
          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Company Name</label>
            <input type="text" [(ngModel)]="driveForm.companyName" name="companyName" required
                   style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;"
                   placeholder="Enter company name">
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Role</label>
            <input type="text" [(ngModel)]="driveForm.role" name="role" required
                   style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;"
                   placeholder="e.g. SDE-1">
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Drive Type</label>
            <select [(ngModel)]="driveForm.driveType" name="driveType"
                    style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;background:white;">
              <option value="EXTERNAL">🌐 External (company-run, apply link only)</option>
              <option value="INTERNAL">🏢 Internal (institute-run, schedulable interview slots)</option>
            </select>
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Package (LPA)</label>
            <input type="number" [(ngModel)]="driveForm.packageAmount" name="packageAmount"
                   style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;"
                   placeholder="e.g. 25">
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Location</label>
            <input type="text" [(ngModel)]="driveForm.location" name="location"
                   style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;"
                   placeholder="e.g. Bangalore">
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Subscription Plan (for access control)</label>
            <select [(ngModel)]="driveForm.planId" name="planId"
                    style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;background:white;">
              <option [ngValue]="null">No plan (free access)</option>
              <option *ngFor="let p of plans" [ngValue]="p.id">{{p.name}} - ₹{{p.price}}{{p.period}}</option>
            </select>
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Deadline</label>
            <input type="datetime-local" [(ngModel)]="driveForm.deadline" name="deadline"
                   style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;">
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Eligibility</label>
            <textarea [(ngModel)]="driveForm.eligibility" name="eligibility" rows="2"
                      style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;resize:vertical;"
                      placeholder="Eligibility criteria"></textarea>
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Description</label>
            <textarea [(ngModel)]="driveForm.description" name="description" rows="3"
                      style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;resize:vertical;"
                      placeholder="Job description"></textarea>
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Apply Link</label>
            <input type="text" [(ngModel)]="driveForm.applyLink" name="applyLink"
                   style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;"
                   placeholder="https://...">
          </div>

          <div style="margin-bottom:20px;">
            <label style="display:block;font-weight:600;margin-bottom:8px;font-size:14px;">Status</label>
            <select [(ngModel)]="driveForm.isActive" name="isActive"
                    style="width:100%;padding:10px 14px;border:1px solid #E2E8F0;border-radius:8px;font-size:14px;background:white;">
              <option [ngValue]="true">Active</option>
              <option [ngValue]="false">Inactive</option>
            </select>
          </div>

          <div style="display:flex;gap:12px;justify-content:flex-end;margin-top:24px;">
            <button type="button" class="btn btn-secondary" (click)="closeModal()">Cancel</button>
            <button type="submit" class="btn btn-primary" [disabled]="saving">{{saving ? 'Saving...' : (editingDrive ? 'Update Drive' : 'Create Drive')}}</button>
          </div>
        </form>

        <div *ngIf="errorMessage" style="margin-top:16px;padding:12px;background:#FEE2E2;color:#991B1B;border-radius:8px;font-size:14px;">
          {{errorMessage}}
        </div>
      </div>
    </div>

    <!-- Interview Slots Modal (INTERNAL drives) -->
    <div class="modal-overlay" *ngIf="showSlotsModal" (click)="closeSlotsModal()">
      <div class="modal-content" style="width:90%;max-width:640px;" (click)="$event.stopPropagation()">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
          <h2 style="font-size:20px;font-weight:700;">Interview Slots — {{ slotsForDrive?.companyName }}</h2>
          <button class="btn btn-secondary" (click)="closeSlotsModal()">✕</button>
        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;">
          <input type="datetime-local" [(ngModel)]="newSlot.slotTime" name="slotTime"
                 style="padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
          <input type="text" [(ngModel)]="newSlot.location" name="slotLocation" placeholder="Location (e.g. Room 204 / Google Meet)"
                 style="padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
          <input type="text" [(ngModel)]="newSlot.notes" name="slotNotes" placeholder="Notes (optional)"
                 style="grid-column:1/-1;padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
        </div>
        <button class="btn btn-primary" (click)="addSlot()" style="margin-bottom:20px;">+ Add Slot</button>

        <table>
          <thead><tr><th>Date & Time</th><th>Location</th><th>Status</th><th>Booked By (User ID)</th><th></th></tr></thead>
          <tbody>
            <tr *ngFor="let s of slots">
              <td style="font-size:13px;">{{ s.slotTime | slice:0:16 }}</td>
              <td>{{ s.location || '-' }}</td>
              <td>
                <span class="badge" [class.badge-success]="s.status === 'BOOKED'" [class.badge-warning]="s.status === 'AVAILABLE'">{{ s.status }}</span>
              </td>
              <td>{{ s.bookedByUserId || '-' }}</td>
              <td><button class="btn btn-danger" style="padding:4px 10px;font-size:12px;" (click)="deleteSlot(s)">Delete</button></td>
            </tr>
            <tr *ngIf="slots.length === 0">
              <td colspan="5" style="text-align:center;color:#64748B;padding:24px;">No interview slots yet. Add one above.</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  `,
  styles: [`
    .modal-overlay {
      position: fixed;
      top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(0,0,0,0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 1000;
    }
    .modal-content {
      background: white;
      border-radius: 16px;
      padding: 32px;
      box-shadow: 0 20px 25px -5px rgba(0,0,0,0.1);
      max-height: 90vh;
      overflow-y: auto;
    }
  `]
})
export class PlacementsComponent implements OnInit {
  drives: Drive[] = [];
  plans: SubscriptionPlan[] = [];
  applications: StudentApplication[] = [];
  showModal = false;
  editingDrive: Drive | null = null;
  saving = false;
  errorMessage = '';

  driveForm: any = {
    companyName: '',
    role: '',
    driveType: 'EXTERNAL',
    packageAmount: null,
    location: '',
    eligibility: '',
    description: '',
    applyLink: '',
    deadline: '',
    isActive: true,
    planId: null
  };

  showSlotsModal = false;
  slotsForDrive: Drive | null = null;
  slots: InterviewSlot[] = [];
  newSlot: { slotTime: string; location: string; notes: string } = { slotTime: '', location: '', notes: '' };

  constructor(private apiService: ApiService) {}

  ngOnInit() {
    this.loadDrives();
    this.loadPlans();
    this.loadApplications();
  }

  loadApplications() {
    this.apiService.get<StudentApplication[]>('/api/student-placements').subscribe({
      next: (data) => { this.applications = data; },
      error: (err) => { console.error('Failed to load applications', err); this.applications = []; }
    });
  }

  updateApplicationStatus(application: StudentApplication, status: string) {
    this.apiService.put(`/api/student-placements/${application.id}/status`, { status }).subscribe({
      next: () => {
        application.status = status as StudentApplication['status'];
      },
      error: (err) => {
        console.error('Failed to update status', err);
        alert('Failed to update application status.');
      }
    });
  }

  loadDrives() {
    this.apiService.get<Drive[]>('/api/placement-drives').subscribe({
      next: (data) => {
        this.drives = data;
      },
      error: (err) => {
        console.error('Failed to load drives', err);
        this.drives = [];
      }
    });
  }

  loadPlans() {
    this.apiService.get<SubscriptionPlan[]>('/api/subscription-plans/admin/all').subscribe({
      next: (data) => {
        this.plans = data;
      },
      error: (err) => {
        console.error('Failed to load subscription plans', err);
        this.plans = [];
      }
    });
  }

  getPlanName(planId?: number): string {
    if (!planId) return '';
    const plan = this.plans.find(p => p.id === planId);
    return plan ? plan.name : '';
  }

  openAddModal() {
    this.editingDrive = null;
    this.errorMessage = '';
    this.driveForm = {
      companyName: '',
      role: '',
      driveType: 'EXTERNAL',
      packageAmount: null,
      location: '',
      eligibility: '',
      description: '',
      applyLink: '',
      deadline: '',
      isActive: true,
      planId: null
    };
    this.showModal = true;
  }

  openEditModal(drive: Drive) {
    this.editingDrive = drive;
    this.errorMessage = '';
    this.driveForm = {
      companyName: drive.companyName,
      role: drive.role,
      driveType: drive.driveType || 'EXTERNAL',
      packageAmount: drive.packageAmount,
      location: drive.location || '',
      eligibility: drive.eligibility || '',
      description: drive.description || '',
      applyLink: drive.applyLink || '',
      deadline: drive.deadline ? drive.deadline.slice(0, 16) : '',
      isActive: drive.isActive,
      planId: drive.planId || null
    };
    this.showModal = true;
  }

  openSlotsModal(drive: Drive) {
    this.slotsForDrive = drive;
    this.newSlot = { slotTime: '', location: drive.location || '', notes: '' };
    this.showSlotsModal = true;
    this.loadSlots(drive.id);
  }

  closeSlotsModal() {
    this.showSlotsModal = false;
    this.slotsForDrive = null;
    this.slots = [];
  }

  loadSlots(driveId: number) {
    this.apiService.get<InterviewSlot[]>(`/api/interview-slots/drive/${driveId}`).subscribe({
      next: (data) => { this.slots = data; },
      error: () => { this.slots = []; }
    });
  }

  addSlot() {
    if (!this.slotsForDrive || !this.newSlot.slotTime) return;
    const payload = {
      driveId: this.slotsForDrive.id,
      slotTime: this.newSlot.slotTime.length === 16 ? `${this.newSlot.slotTime}:00` : this.newSlot.slotTime,
      location: this.newSlot.location,
      notes: this.newSlot.notes
    };
    this.apiService.post('/api/interview-slots', payload).subscribe({
      next: () => {
        this.loadSlots(this.slotsForDrive!.id);
        this.newSlot = { slotTime: '', location: this.slotsForDrive!.location || '', notes: '' };
      },
      error: () => alert('Failed to add interview slot')
    });
  }

  deleteSlot(slot: InterviewSlot) {
    if (!confirm('Delete this interview slot?')) return;
    this.apiService.delete(`/api/interview-slots/${slot.id}`).subscribe({
      next: () => this.loadSlots(this.slotsForDrive!.id),
      error: () => alert('Failed to delete slot')
    });
  }

  closeModal(event?: any) {
    this.showModal = false;
    this.editingDrive = null;
    this.errorMessage = '';
  }

  saveDrive() {
    this.saving = true;
    this.errorMessage = '';

    if (this.editingDrive) {
      this.apiService.put(`/api/placement-drives/${this.editingDrive.id}`, this.driveForm).subscribe({
        next: () => {
          this.saving = false;
          this.loadDrives();
          this.closeModal();
        },
        error: (err) => {
          this.saving = false;
          console.error('Failed to update drive', err);
          this.errorMessage = 'Failed to update drive. ' + (err.error?.message || 'Please check the details and try again.');
        }
      });
    } else {
      this.apiService.post('/api/placement-drives', this.driveForm).subscribe({
        next: () => {
          this.saving = false;
          this.loadDrives();
          this.closeModal();
        },
        error: (err) => {
          this.saving = false;
          console.error('Failed to create drive', err);
          this.errorMessage = 'Failed to create drive. ' + (err.error?.message || 'Please check the details and try again.');
        }
      });
    }
  }

  deleteDrive(drive: Drive) {
    if (!confirm(`Are you sure you want to delete "${drive.companyName}" drive?`)) return;
    this.apiService.delete(`/api/placement-drives/${drive.id}`).subscribe({
      next: () => {
        this.loadDrives();
      },
      error: (err) => {
        console.error('Failed to delete drive', err);
        alert('Failed to delete drive');
      }
    });
  }
}
